import java.util.HashMap;
import java.util.Map;
import java.util.function.UnaryOperator;

public class Solution {
    record Bucket(double tokens, long ultimoRefillMillis) {}

    interface EstadoCompartilhado {
        Bucket atualizar(String chave, UnaryOperator<Bucket> operacao);
    }

    static class RateLimiterDistribuido {
        private final EstadoCompartilhado store;
        private final int capacidade;
        private final double tokensPorSegundo;

        RateLimiterDistribuido(EstadoCompartilhado store, int capacidade, double tokensPorSegundo) {
            if (store == null) throw new IllegalArgumentException("store obrigatorio");
            if (capacidade <= 0) throw new IllegalArgumentException("capacidade invalida");
            if (tokensPorSegundo <= 0) throw new IllegalArgumentException("taxa invalida");
            this.store = store;
            this.capacidade = capacidade;
            this.tokensPorSegundo = tokensPorSegundo;
        }

        boolean permitir(String usuario, int custo, long agoraMillis) {
            exigirUsuario(usuario);
            if (custo <= 0) throw new IllegalArgumentException("custo invalido");

            boolean[] permitido = {false};
            store.atualizar(chave(usuario), atual -> {
                double saldo = recarregar(atual, agoraMillis);
                long ultimo = atual == null ? agoraMillis : Math.max(atual.ultimoRefillMillis(), agoraMillis);
                if (saldo >= custo) {
                    saldo -= custo;
                    permitido[0] = true;
                }
                return new Bucket(saldo, ultimo);
            });
            return permitido[0];
        }

        double tokens(String usuario, long agoraMillis) {
            exigirUsuario(usuario);
            Bucket atual = store.atualizar(chave(usuario), b -> b);
            return recarregar(atual, agoraMillis);
        }

        private double recarregar(Bucket atual, long agoraMillis) {
            if (atual == null) return capacidade;
            long delta = Math.max(0, agoraMillis - atual.ultimoRefillMillis());
            return Math.min(capacidade,
                atual.tokens() + delta * tokensPorSegundo / 1000.0);
        }

        private String chave(String usuario) { return "bucket:" + usuario; }

        private void exigirUsuario(String usuario) {
            if (usuario == null || usuario.isBlank()) {
                throw new IllegalArgumentException("usuario obrigatorio");
            }
        }
    }
}

