import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.HashMap;
import java.util.Map;
import java.util.function.UnaryOperator;

class SolutionTest {
    static class StoreFake implements Solution.EstadoCompartilhado {
        final Map<String, Solution.Bucket> dados = new HashMap<>();

        public Solution.Bucket atualizar(String chave, UnaryOperator<Solution.Bucket> operacao) {
            var novo = operacao.apply(dados.get(chave));
            dados.put(chave, novo);
            return novo;
        }
    }

    @Test void consomeAteACapacidade() {
        var rl = new Solution.RateLimiterDistribuido(new StoreFake(), 3, 1.0);
        assertTrue(rl.permitir("ana", 1, 0));
        assertTrue(rl.permitir("ana", 1, 0));
        assertTrue(rl.permitir("ana", 1, 0));
        assertFalse(rl.permitir("ana", 1, 0));
        assertEquals(0.0, rl.tokens("ana", 0), 0.0001);
    }

    @Test void recarregaComOTempo() {
        var rl = new Solution.RateLimiterDistribuido(new StoreFake(), 3, 1.0);
        assertTrue(rl.permitir("ana", 2, 0));
        assertEquals(1.0, rl.tokens("ana", 0), 0.0001);
        assertEquals(2.0, rl.tokens("ana", 1000), 0.0001);
        assertTrue(rl.permitir("ana", 1, 1000));
    }

    @Test void recargaNaoPassaDaCapacidade() {
        var rl = new Solution.RateLimiterDistribuido(new StoreFake(), 3, 10.0);
        assertTrue(rl.permitir("ana", 1, 0));
        assertEquals(3.0, rl.tokens("ana", 60_000), 0.0001);
    }

    @Test void duasInstanciasCompartilhamLimite() {
        var store = new StoreFake();
        var nodeA = new Solution.RateLimiterDistribuido(store, 3, 1.0);
        var nodeB = new Solution.RateLimiterDistribuido(store, 3, 1.0);

        assertTrue(nodeA.permitir("ana", 2, 0));
        assertTrue(nodeB.permitir("ana", 1, 0));
        assertFalse(nodeA.permitir("ana", 1, 0));
        assertFalse(nodeB.permitir("ana", 1, 0));
    }

    @Test void custoMaiorQueCapacidadeSempreFalha() {
        var rl = new Solution.RateLimiterDistribuido(new StoreFake(), 2, 100.0);
        assertFalse(rl.permitir("ana", 3, 0));
        assertEquals(2.0, rl.tokens("ana", 0), 0.0001);
    }

    @Test void usuariosIndependentes() {
        var rl = new Solution.RateLimiterDistribuido(new StoreFake(), 1, 1.0);
        assertTrue(rl.permitir("ana", 1, 0));
        assertFalse(rl.permitir("ana", 1, 0));
        assertTrue(rl.permitir("bruno", 1, 0));
    }

    @Test void relogioRegredindoNaoRecarrega() {
        var rl = new Solution.RateLimiterDistribuido(new StoreFake(), 2, 1.0);
        assertTrue(rl.permitir("ana", 1, 10_000));
        assertEquals(1.0, rl.tokens("ana", 5_000), 0.0001);
    }

    @Test void validacoes() {
        assertThrows(IllegalArgumentException.class,
            () -> new Solution.RateLimiterDistribuido(new StoreFake(), 0, 1.0));
        assertThrows(IllegalArgumentException.class,
            () -> new Solution.RateLimiterDistribuido(new StoreFake(), 1, 0));
        var rl = new Solution.RateLimiterDistribuido(new StoreFake(), 2, 1.0);
        assertThrows(IllegalArgumentException.class, () -> rl.permitir("", 1, 0));
        assertThrows(IllegalArgumentException.class, () -> rl.permitir("ana", 0, 0));
    }
}
